#include <bits/stdc++.h>
using namespace std;

struct Mod998 {
    static const long long MOD = 998244353LL;

    static long long add(long long a, long long b) {
        a %= MOD; b %= MOD;
        long long res = a + b;
        if (res >= MOD) res -= MOD;
        return res;
    }

    static long long subtract(long long a, long long b) {
        a %= MOD; b %= MOD;
        long long res = a - b;
        if (res < 0) res += MOD;
        return res;
    }

    static long long mult(long long a, long long b) {
        return (a % MOD) * (b % MOD) % MOD;
    }

    static long long pow(long long base, long long exp) {
        long long result = 1;
        long long b = base % MOD;
        while (exp > 0) {
            if (exp & 1) result = mult(result, b);
            b = mult(b, b);
            exp >>= 1;
        }
        return result;
    }

    static long long inv(long long a) {
        // Fermat's little theorem, since MOD is prime
        return pow(a, MOD - 2);
    }

    static long long nCr(long long n, long long r, vector<long long>& fact, vector<long long>& invFact) {
        if (r < 0 || r > n) return 0;
        return mult(fact[n], mult(invFact[r], invFact[n - r]));
    }

    static void precomputeFactorials(int maxN, vector<long long>& fact, vector<long long>& invFact) {
        fact.resize(maxN + 1);
        invFact.resize(maxN + 1);
        fact[0] = 1;
        for (int i = 1; i <= maxN; i++) {
            fact[i] = mult(fact[i - 1], i);
        }
        invFact[maxN] = inv(fact[maxN]);
        for (int i = maxN - 1; i >= 0; i--) {
            invFact[i] = mult(invFact[i + 1], i + 1);
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    // Precompute factorials for nCr
    vector<long long> fact, invFact;
    int maxN = n + m + 10; // buffer
    Mod998::precomputeFactorials(maxN, fact, invFact);

    // Compute modular inverse of (n + m)
    long long invNPlusM = Mod998::inv(n + m);

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; ; i++) {
        long long denom = Mod998::inv(n + m - i);
        p = Mod998::mult(p, n - i);
        p = Mod998::mult(p, denom);
        if (p == 0) break;
        phaseSize = Mod998::add(phaseSize, p);
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long numPhases = Mod998::mult(m + k, Mod998::inv(k));
        long long term = Mod998::mult(Mod998::nCr(n, k, fact, invFact), numPhases);
        term = Mod998::mult(term, phaseSize);
        if (k % 2 == 1) {
            answer = Mod998::add(answer, term);
        } else {
            answer = Mod998::subtract(answer, term);
        }
    }

    cout << answer << "\n";

    return 0;
}
